create table xxventuri.xxeba_products_upload_t (
    stock_code         varchar2(100 byte),
    product_name       varchar2(2000 byte),
    product_type       varchar2(100 byte),
    product_group      varchar2(1000 byte),
    brand_name         varchar2(1000 byte),
    cat_number         varchar2(100 byte),
    hsn_code           varchar2(100 byte),
    tariff_code        varchar2(100 byte),
    unit_price         varchar2(100 byte),
    currency           varchar2(100 byte),
    product_cost       varchar2(100 byte),
    uom                varchar2(100 byte),
    lead_time          varchar2(100 byte),
    min_order_quantity varchar2(100 byte)
);


